    max_line_length = 998
    lines = message.split(b'\r\n')
    result_lines = []

    for line in lines:
        if len(line) > max_line_length:
            # Split the line into chunks
            for i in range(0, len(line), max_line_length):
                result_lines.append(line[i:i+max_line_length])
        else:
            result_lines.append(line)

    return b'\r\n'.join(result_lines) + b'\r\n'

def main():
    try:
        stdin_content = input().strip()
        if not stdin_content:
            raise ValueError
        req = json.loads(stdin_content)
        validate_request(req)
    except (ValueError, json.JSONDecodeError, EOFError):
        print(json.dumps({"error": "invalid_request"}))
        return

    message_bytes = build_message(req)
    message_b64 = base64.b64encode(message_bytes).decode('ascii')
    sha256 = hashlib.sha256(message_bytes).hexdigest()

    result = {
        "format": "eml",
        "message_b64": message_b64,
        "sha256": sha256
    }
    print(json.dumps(result))

if __name__ == "__main__":
    main()
